def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    def count_defects(seq):
        total = 0
        for x in seq:
            if x == 'D':
                total += 1
        return total

    opp_def = count_defects(op)
    my_def = count_defects(my)

    if n < 4:
        return 'C'

    if n >= 99:
        return 'D'

    recent_op = op[-8:]
    recent_my = my[-8:]
    recent_opp_def = count_defects(recent_op)
    recent_my_def = count_defects(recent_my)

    last_opp = op[-1]
    last_my = my[-1]

    # Detect exploitative opponents: our cooperation punished repeatedly.
    exploitations = 0
    for i in range(n):
        if my[i] == 'C' and op[i] == 'D':
            exploitations += 1
    if exploitations >= 5 and exploitations * 2 > n:
        # They consistently take advantage; defend unless they've just shown good faith.
        if last_opp == 'C' and recent_opp_def <= 1:
            return 'C'
        return 'D'

    # Clear exploiter / heavy defector
    if recent_opp_def >= 6:
        return 'D'

    if recent_opp_def >= 4:
        if last_opp == 'D':
            return 'D'
        if n % 4 == 0:
            return 'C'
        return 'D'

    # Strongly cooperative opponent: keep cooperation, but take a final-round edge
    # and occasionally probe.
    if opp_def == 0:
        if n >= 95:
            return 'D'
        if n >= 20 and n % 13 == 0:
            return 'D'
        return 'C'

    # If opponent has been very cooperative in recent window, cooperate;
    # occasional probe if we are close to the end and can gain.
    if recent_opp_def == 0:
        if n >= 90:
            return 'C' if last_opp == 'C' else 'D'
        if n >= 30 and n % 17 == 0:
            return 'D'
        return 'C'

    # Mutual defection spiral: escape occasionally.
    if last_opp == 'D' and last_my == 'D':
        run = 0
        for i in range(n - 1, -1, -1):
            if op[i] == 'D' and my[i] == 'D':
                run += 1
            else:
                break
        if run >= 3:
            if rng.random() < 0.4:
                return 'C'
            return 'D'
        return 'D'

    # Opponent defected but we cooperated: strong retaliation, short memory.
    if last_opp == 'D' and last_my == 'C':
        if recent_opp_def >= 2:
            return 'D'
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent cooperated. If we defected last, restore cooperation often.
    if last_opp == 'C':
        if last_my == 'D':
            if recent_opp_def >= 3:
                return 'D'
            return 'C'
        # Both cooperating. Probe rarely, mostly stay cooperative.
        if n >= 80:
            if opp_def * 4 < n:
                return 'C'
            return 'D' if recent_opp_def >= 2 else 'C'
        if opp_def * 3 < n and n >= 25 and n % 19 == 0:
            return 'D'
        return 'C'

    return 'C'
